  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [240+Math.sin(t*0.6)*120+Math.cos(t*0.9)*40, 120+Math.cos(t*0.4)*80+Math.sin(t*0.7)*30, 0.07, 2.0, 1.0],
    [160+Math.cos(t*0.5)*100+Math.sin(t*1.1)*30, 80+Math.sin(t*0.7)*60+Math.cos(t*0.3)*40, 0.09, 1.7, 0.85],
    [320+Math.sin(t*0.3+2)*100+Math.cos(t*0.8)*50, 160+Math.cos(t*0.5+1)*70+Math.sin(t*0.6)*30, 0.055, 2.3, 1.15],
    [120+Math.cos(t*0.8+1)*90+Math.sin(t*1.3)*20, 180+Math.sin(t*0.6+3)*70+Math.cos(t*0.4)*25, 0.11, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*80+Math.cos(t*0.6)*30, 60+Math.cos(t*0.9+2)*60+Math.sin(t*0.5)*35, 0.065, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*110+Math.sin(t*0.75)*25, 200+Math.sin(t*0.55)*70+Math.cos(t*0.85)*20, 0.08, 1.9, 0.9],
    [80+Math.sin(t*0.45+1)*70+Math.cos(t*0.65)*20, 40+Math.cos(t*0.55+3)*50+Math.sin(t*0.35)*30, 0.13, 1.4, 0.65]
  ];
  let aS=0,iS=0,aS2=0,iS2=0,tw=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2=Math.sqrt((sx-sX*0.7-cx*0.3)**2+(sy-sY*0.7-cy*0.3)**2);
    aS+=Math.sin(d*f-t*sp)*w; iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    aS2+=Math.sin(d2*f*1.3-t*sp*0.8+2)*w*0.5; iS2+=Math.sin(d2*f*0.5+t*sp*0.4+0.7)*w*0.5;
    tw+=w;
  }
  const act=(aS+aS2)/(tw*1.5), inh=(iS+iS2)/(tw*1.5);
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t))/2
    +Math.sin((sx+sy)*0.11+t*2.2)*0.15+Math.sin((sx-sy)*0.09-t*1.8)*0.15+Math.sin(sx*0.06+sy*0.04-t*0.5)*0.1;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
