  const rings=Math.sin(dist*0.08-t*2)*Math.exp(-dist*0.003)*0.5;
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.4+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.25;
  const rd1=Math.tanh((act-inh*0.65+bg*0.25+spiral+rings)*2);
  const rd2=Math.tanh((act*0.8-inh+bg*0.4-spiral*0.5+cell)*1.8);
  const reaction=(rd1+rd2)*0.5;
  const v=(reaction*0.7+cell*0.2+rings*0.1)*0.5+0.5;
  const pal=[[5,12,52],[12,45,95],[18,85,125],[25,140,135],[80,175,120],[180,190,70],[220,170,50],[215,120,55],[190,70,60],[150,45,80],[90,30,75],[40,18,60],[5,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i, cf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15, edge=Math.abs(reaction)>0.65?1.12:1, hl=Math.max(0,reaction-0.6)*0.8;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*cf)*lum*edge+hl*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*cf)*lum*edge+hl*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*cf)*lum*edge+hl*50)|0)
  ];
}
